Repair the following Java 8 code so that it correctly solves the programming problem. The code reads and writes I/O from the console. Your repaired code should implement the problem correctly, meaning that it should produce the correct output for any valid input.
Print your repaired code and also the confidence score you give to your repair. The confidence score should be a number between 0 and 1. The format of the output should be:
<repaired_code>
<your_repaired_code>
</repaired_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
One day Greg and his friends were walking in the forest. Overall there were n people walking, including Greg. Soon he found himself in front of a river. The guys immediately decided to get across the river. Luckily, there was a boat by the river bank, just where the guys were standing. We know that the boat can hold people with the total weight of at most k kilograms.Greg immediately took a piece of paper and listed there the weights of all people in his group (including himself). It turned out that each person weights either 50 or 100 kilograms. Now Greg wants to know what minimum number of times the boat needs to cross the river to transport the whole group to the other bank. The boat needs at least one person to navigate it from one bank to the other. As the boat crosses the river, it can have any non-zero number of passengers as long as their total weight doesn't exceed k.Also Greg is wondering, how many ways there are to transport everybody to the other side in the minimum number of boat rides. Two ways are considered distinct if during some ride they have distinct sets of people on the boat.Help Greg with this problem. 
</problem_description>

Here is the Java 8 code you have to repair:
<original_code>
<your_rewritten_code_1>
import java.io.*;
import java.util.*;

public class CF295C_ {

    static int[][][] dp1;
    static int[][][][] dp2;
    static int k;
    static final int MOD = 1000000007;
    static int F, H;
    static boolean[][][] visited;
    static long[][] nCrTable;

    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);

        int n = sc.nextInt();
        k = sc.nextInt();
        for (int i = 0; i < n; i++) {
            if (sc.nextInt() == 50) F++;
            else H++;
        }

        initCombinations();
        initDp1();
        int min = solve(F, H, 0);
        if (min > 100000) {
            System.out.println(-1);
            System.out.println(0);
            return;
        }

        initDp2(min);
        System.out.println(min);
        System.out.println(solve2(F, H, 0, min));

        pw.flush();
        pw.close();
    }

    private static void initCombinations() {
        nCrTable = new long[100][100];
        for (long[] row : nCrTable) Arrays.fill(row, -1);
    }

    private static void initDp1() {
        dp1 = new int[2][51][51];
        visited = new boolean[2][51][51];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 51; j++) {
                Arrays.fill(dp1[i][j], -1);
            }
        }
    }

    private static void initDp2(int minVal) {
        dp2 = new int[2][51][51][minVal + 1];
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 51; j++) {
                for (int l = 0; l <= minVal; l++) {
                    Arrays.fill(dp2[i][j][l], -1);
                }
            }
        }
    }

    static int solve(int fifty, int hundred, int side) {
        if (fifty + hundred == 0 && side == 0) return 0;
        if (fifty == F && hundred == H && side == 1) return 0;

        if (dp1[side][fifty][hundred] != -1) return dp1[side][fifty][hundred];
        if (visited[side][fifty][hundred]) return 1_000_000_000;
        visited[side][fifty][hundred] = true;

        int ans = 1_000_000_000;
        for (int ff = 0; ff <= fifty; ff++) {
            for (int hh = 0; hh <= hundred; hh++) {
                if (hh + ff == 0 || hh * 100 + ff * 50 > k) continue;
                ans = Math.min(ans, 1 + solve(F - fifty + ff, H - hundred + hh, 1 ^ side));
            }
        }
        return dp1[side][fifty][hundred] = ans;
    }

    static int solve2(int fifty, int hundred, int side, int minSteps) {
        if (minSteps < 0) return 0;
        if (fifty + hundred == 0 && side == 0) return minSteps == 0 ? 1 : 0;
        if (fifty == F && hundred == H && side == 1) return minSteps == 0 ? 1 : 0;
        if (minSteps == 0) return 0;

        if (dp2[side][fifty][hundred][minSteps] != -1) {
            return dp2[side][fifty][hundred][minSteps];
        }

        int result = 0;
        for (int ff = 0; ff <= fifty; ff++) {
            for (int hh = 0; hh <= hundred; hh++) {
                if (hh + ff == 0 || hh * 100 + ff * 50 > k) continue;
                long ways = (nCr(fifty, ff) * nCr(hundred, hh)) % MOD;
                int subResult = solve2(F - fifty + ff, H - hundred + hh, 1 ^ side, minSteps - 1);
                result = (int) ((result + ways * subResult) % MOD);
            }
        }
        return dp2[side][fifty][hundred][minSteps] = result;
    }

    static long nCr(int n, int r) {
        if (r > n || r < 0) return 0;
        if (r == 0 || r == n) return 1;
        if (nCrTable[n][r] != -1) return nCrTable[n][r];
        if (r > n - r) r = n - r;
        return nCrTable[n][r] = (nCr(n - 1, r - 1) + nCr(n - 1, r)) % MOD;
    }

    static class Scanner {
        private BufferedReader br;
        private StringTokenizer st;

        public Scanner(InputStream s) {
            br = new BufferedReader(new InputStreamReader(s));
        }

        public Scanner(String s) throws FileNotFoundException {
            br = new BufferedReader(new FileReader(new File(s)));
        }

        public String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                st = new StringTokenizer(br.readLine());
            }
            return st.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public String nextLine() throws IOException {
            return br.readLine();
        }

        public boolean ready() throws IOException {
            return br.ready();
        }
    }
}
